use std::fs

fn all_digits(s: string) -> bool {
    if s.len() == 0 { return false }
    for c in s.chars() {
        if c < '0' || c > '9' { return false }
    }
    true
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut us: Vec<string> = []
    let mut acts: Vec<string> = []
    let mut secs: Vec<int> = []
    let mut bad = 0
    for line in text.lines() {
        let toks: Vec<string> = line.split_whitespace().collect()
        if toks.len() != 3 || !all_digits(toks[2]) {
            bad += 1
            continue
        }
        us.push(toks[0])
        acts.push(toks[1])
        secs.push(toks[2].parse::<int>().unwrap_or(0))
    }
    let n: int = us.len() as int
    let mut names: Vec<string> = []
    let mut totals: Vec<int> = []
    let mut cnts: Vec<int> = []
    let mut i = 0
    while i < n {
        let u = us[i as usize]
        let mut idx: int = -1
        let mut j = 0
        while j < names.len() as int {
            if names[j as usize] == u { idx = j }
            j += 1
        }
        if idx < 0 {
            names.push(u)
            totals.push(secs[i as usize])
            cnts.push(1)
        } else {
            totals[idx as usize] = totals[idx as usize] + secs[i as usize]
            cnts[idx as usize] = cnts[idx as usize] + 1
        }
        i += 1
    }
    let m: int = names.len() as int
    let mut order: Vec<int> = []
    let mut k = 0
    while k < m {
        order.push(k)
        k += 1
    }
    let mut a = 0
    while a < m {
        let mut b = a + 1
        while b < m {
            let oa = order[a as usize]
            let ob = order[b as usize]
            let ta = totals[oa as usize]
            let tb = totals[ob as usize]
            let swap = tb > ta || (tb == ta && names[ob as usize] < names[oa as usize])
            if swap {
                order[a as usize] = ob
                order[b as usize] = oa
            }
            b += 1
        }
        a += 1
    }
    for o in order {
        let u = names[o as usize]
        let mut best = ""
        let mut bc = 0
        let mut p = 0
        while p < n {
            if us[p as usize] == u {
                let act = acts[p as usize]
                let mut c = 0
                let mut q = 0
                while q < n {
                    if us[q as usize] == u && acts[q as usize] == act { c += 1 }
                    q += 1
                }
                if c > bc || (c == bc && act < best) {
                    bc = c
                    best = act
                }
            }
            p += 1
        }
        println("${u} ${cnts[o as usize]} ${totals[o as usize]} ${best}")
    }
    println("malformed: ${bad}")
}

